 "content": "from collections import Counter


def transform(grid):
    """Paint the shortest non-empty background suffix among patterned rows."""
    if not grid:
        return []
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []
    for r, row in enumerate(grid):
        if not any(v != bg for v in row):
            continue
        n = 0
        for v in reversed(row):
            if v != bg:
                break
            n += 1
        if n:
            candidates.append((n, r))
    if candidates:
        shortest = min(n for n, _ in candidates)
        for n, r in candidates:
            if n == shortest:
                out[r][-n:] = [1] * n
    return out


